            make(84, "Al-Inshiqaq", 1, "إِذَا السَّمَاءُ انشَقَّتْ", "إِذَا <hamzat_wasl>ال</hamzat_wasl><madd>سَّمَاءُ</madd> ان<ikhfa>شَقَّتْ</ikhfa>", "Idhas-sama'un-shaqqat", "When the sky has split open", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD, TajweedRuleType.GHUNNAH)),
            make(84, "Al-Inshiqaq", 2, "وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ", "وَأَذِنَتْ لِرَبِّهَا وَحُ<tafkhim>قَّتْ</tafkhim>", "Wa adhinat li-rabbiha wa huqqat", "And has listened to its Lord and was obligated [to do so]", listOf(TajweedRuleType.TAFKHIM)),
