            make(84, "Al-Inshiqaq", 4, "وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ", "وَأَلْ<tafkhim>قَتْ</tafkhim> مَا فِيهَا وَتَخَلَّتْ", "Wa alqat ma fiha wa takhallat", "And has cast out that which was within it and relinquished [it]", listOf(TajweedRuleType.TAFKHIM)),
            make(84, "Al-Inshiqaq", 5, "وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ", "وَأَذِنَتْ لِرَبِّهَا وَحُ<tafkhim>قَّتْ</tafkhim>", "Wa adhinat li-rabbiha wa huqqat", "And has listened to its Lord and was obligated [to do so]", listOf(TajweedRuleType.TAFKHIM)),
            make(84, "Al-Inshiqaq", 6, "يَا أَيُّهَا الْإِنسَانُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدْحًا فَمُلَاقِيهِ", "يَا <madd>أَيُّهَا</madd> <hamzat_wasl>الْ</hamzat_wasl>إِ<ikhfa>نسَانُ</ikhfa> <ghunnah>إِنَّكَ</ghunnah> كَادِحٌ إِلَىٰ رَبِّكَ <qalqalah>كَدْحًا</qalqalah> فَمُ<tafkhim>لَاقِيهِ</tafkhim>", "Ya ayyuhal-insanu innaka kadihun ila rabbika kadhan famulaqih", "O mankind, indeed you are laboring toward your Lord with [great] exertion and will meet Him.", listOf(TajweedRuleType.MADD, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH, TajweedRuleType.QALQALAH, TajweedRuleType.TAFKHIM)),
            make(84, "Al-Inshiqaq", 7, "فَأَمَّا مَنْ أُوتِيَ كِتَابَهُ بِيَمِينِهِ", "فَ<ghunnah>أَمَّا</ghunnah> مَنْ <madd>أُوتِيَ</madd> كِتَابَهُ بِيَمِينِهِ", "Fa-amma man utiya kitabahu biyaminih", "Then as for he who is given his record in his right hand,", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.MADD)),
            make(84, "Al-Inshiqaq", 8, "فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا", "فَسَوْفَ يُحَاسَبُ حِسَابًا <idgham>يَسِيرًا</idgham>", "Fasawfa yuhasabu hisabay yasira", "He will be judged with an easy account", listOf(TajweedRuleType.IDGHAM)),
            make(84, "Al-Inshiqaq", 9, "وَيَنقَلِبُ إِلَىٰ أَهْلِهِ مَسْرُورًا", "وَيَن<ikhfa>قَلِبُ</ikhfa> إِلَىٰ <madd>أَهْلِهِ</madd> مَسْرُورًا", "Wa yanqalibu ila ahlihi masrura", "And return to his people in happiness.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.MADD)),
            make(84, "Al-Inshiqaq", 10, "وَأَمَّا مَنْ أُوتِيَ كِتَابَهُ وَرَاءَ ظَهْرِهِ", "وَ<ghunnah>أَمَّا</ghunnah> مَنْ <madd>أُوتِيَ</madd> كِتَابَهُ <madd>وَرَاءَ</madd> <tafkhim>ظَهْرِهِ</tafkhim>", "Wa amma man utiya kitabahu wara'a zahrih", "But as for he who is given his record behind his back,", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.MADD, TajweedRuleType.TAFKHIM)),
            make(84, "Al-Inshiqaq", 11, "فَسَوْفَ يَدْعُو ثُبُورًا", "فَسَوْفَ <qalqalah>يَدْعُو</qalqalah> ثُبُورًا", "Fasawfa yad'u thubura", "He will cry out for destruction", listOf(TajweedRuleType.QALQALAH)),
            make(84, "Al-Inshiqaq", 12, "وَيَصْلَىٰ سَعِيرًا", "وَ<tafkhim>يَصْلَىٰ</tafkhim> سَعِيرًا", "Wa yasla sa'ira", "And [enter to] burn in a Blaze.", listOf(TajweedRuleType.TAFKHIM)),
            make(84, "Al-Inshiqaq", 13, "إِنَّهُ كَانَ فِي أَهْلِهِ مَسْرُورًا", "<ghunnah>إِنَّهُ</ghunnah> كَانَ فِي <madd>أَهْلِهِ</madd> مَسْرُورًا", "Innahu kana fi ahlihi masrura", "Indeed, he had [once] been among his people in happiness;", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.MADD)),
            make(84, "Al-Inshiqaq", 14, "إِنَّهُ ظَنَّ أَن لَّن يَحُورَ", "<ghunnah>إِنَّهُ</ghunnah> <tafkhim>ظَنَّ</tafkhim> <idgham>أَن لَّن</idgham> <idgham>يَحُورَ</idgham>", "Innahu zanna al lay yahur", "Indeed, he thought he would never return [to Allah].", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.TAFKHIM, TajweedRuleType.IDGHAM)),
            make(84, "Al-Inshiqaq", 15, "بَلَىٰ إِنَّ رَبَّهُ كَانَ بِهِ بَصِيرًا", "بَلَىٰ <ghunnah>إِنَّ</ghunnah> رَبَّهُ كَانَ بِهِ <tafkhim>بَصِيرًا</tafkhim>", "Bala inna rabbahu kana bihi basira", "But yes! Indeed, his Lord was ever of him, Seeing.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.TAFKHIM)),
            make(84, "Al-Inshiqaq", 16, "فَلَا أُقْسِمُ بِالشَّفَقِ", "فَلَا <madd>أُ</madd><qalqalah>قْسِمُ</qalqalah> بِ<hamzat_wasl>ال</hamzat_wasl>شَّفَ<qalqalah>قِ</qalqalah>", "Fala uqsimu bish-shafaq", "So I swear by the twilight glow", listOf(TajweedRuleType.MADD, TajweedRuleType.QALQALAH, TajweedRuleType.HAMZAT_WASL)),
            make(84, "Al-Inshiqaq", 17, "وَاللَّيْلِ وَمَا وَسَقَ", "وَ<hamzat_wasl>ال</hamzat_wasl>لَّيْلِ وَمَا وَسَ<tafkhim>قَ</tafkhim>", "Wal-layli wa ma wasaq", "And [by] the night and what it envelops", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(84, "Al-Inshiqaq", 18, "وَالْقَمَرِ إِذَا اتَّسَقَ", "وَ<hamzat_wasl>الْ</hamzat_wasl><tafkhim>قَمَرِ</tafkhim> إِذَا <hamzat_wasl>ا</hamzat_wasl>تَّسَ<tafkhim>قَ</tafkhim>", "Wal-qamari idhat-tasaq", "And [by] the moon when it becomes full", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(84, "Al-Inshiqaq", 19, "لَتَرْكَبُنَّ طَبَقًا عَن طَبَقٍ", "لَتَرْكَبُ<ghunnah>نَّ</ghunnah> <tafkhim>طَبَقًا</tafkhim> عَن <ikhfa><tafkhim>طَبَقٍ</tafkhim></ikhfa>", "Latarkabunna tabaqan 'an tabaq", "[That] you will embark upon stage after stage.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.TAFKHIM)),
            make(84, "Al-Inshiqaq", 20, "فَمَا لَهُمْ لَا يُؤْمِنُونَ", "فَمَا لَهُمْ لَا يُؤْمِنُونَ", "Fama lahum la yu'minun", "So what is [the matter] with them that they do not believe,", emptyList()),
            make(84, "Al-Inshiqaq", 21, "وَإِذَا قُرِئَ عَلَيْهِمُ الْقُرْآنُ لَا يَسْجُدُونَ ۩", "وَإِذَا <tafkhim>قُرِئَ</tafkhim> عَلَيْهِمُ <hamzat_wasl>الْ</hamzat_wasl><tafkhim>قُرْآنُ</tafkhim> لَا يَسْجُدُونَ ۩", "Wa idha quri'a 'alayhimul-qur'anu la yasjudun", "And when the Qur'an is recited to them, they do not prostrate? [Sajdah]", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.HAMZAT_WASL)),
            make(84, "Al-Inshiqaq", 22, "بَلِ الَّذِينَ كَفَرُوا يُكَذِّبُونَ", "بَلِ <hamzat_wasl>الَّذِينَ</hamzat_wasl> كَفَرُوا يُكَذِّبُونَ", "Balil-ladhina kafaru yukadhdhibun", "Rather, those who have disbelieved deny,", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(84, "Al-Inshiqaq", 23, "وَاللَّهُ أَعْلَمُ بِمَا يُوعُونَ", "وَ<hamzat_wasl>ال</hamzat_wasl><tafkhim>لَّهُ</tafkhim> أَعْلَمُ بِمَا يُوعُونَ", "Wal-lahu a'lamu bima yu'un", "And Allah is most knowing of what they keep within themselves.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(84, "Al-Inshiqaq", 24, "فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ", "فَبَشِّرْهُم <ikhfa>بِعَذَابٍ</ikhfa> أَلِيمٍ", "Fabashshirhum bi'adhabin alim", "So give them tidings of a painful punishment,", listOf(TajweedRuleType.GHUNNAH)),
            make(84, "Al-Inshiqaq", 25, "إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ", "إِلَّا <hamzat_wasl>الَّذِينَ</hamzat_wasl> <madd>آمَنُوا</madd> وَعَمِلُوا <hamzat_wasl>ال</hamzat_wasl><tafkhim>صَّالِحَاتِ</tafkhim> لَهُمْ أَ<qalqalah>جْرٌ</qalqalah> غَيْرُ مَمْنُونٍ", "Illal-ladhina amanu wa 'amilus-salihati lahum ajrun ghayru mamnun", "Except for those who believe and do righteous deeds; for them is a reward uninterrupted.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD, TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),

            // ==================== SURAH 85: AL-BURUJ (22 Verses) ====================
            make(85, "Al-Buruj", 1, "وَالسَّمَاءِ ذَاتِ الْبُرُوجِ", "وَ<hamzat_wasl>ال</hamzat_wasl><madd>سَّمَاءِ</madd> ذَاتِ <hamzat_wasl>الْ</hamzat_wasl><qalqalah>بُرُوجِ</qalqalah>", "Was-sama'i dhatil-buruj", "By the sky containing great stars", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD, TajweedRuleType.QALQALAH)),
            make(85, "Al-Buruj", 2, "وَالْيَوْمِ الْمَوْعُودِ", "وَ<hamzat_wasl>الْ</hamzat_wasl>يَوْمِ <hamzat_wasl>الْ</hamzat_wasl>مَوْعُودِ", "Wal-yawmil-maw'ud", "And [by] the promised Day", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(85, "Al-Buruj", 3, "وَشَاهِدٍ وَمَشْهُودٍ", "وَشَاهِدٍ <idgham>وَمَشْهُودٍ</idgham>", "Wa shahidiw wa mashhud", "And [by] the witness and what is witnessed,", listOf(TajweedRuleType.IDGHAM)),
            make(85, "Al-Buruj", 4, "قُتِلَ أَصْحَابُ الْأُخْدُودِ", "<tafkhim>قُتِلَ</tafkhim> أَ<tafkhim>صْحَابُ</tafkhim> <hamzat_wasl>الْ</hamzat_wasl>أُ<qalqalah>خْدُودِ</qalqalah>", "Qutila ashabul-ukhdud", "Cursed were the companions of the trench", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.HAMZAT_WASL)),
            make(85, "Al-Buruj", 5, "النَّارِ ذَاتِ الْوَقُودِ", "<hamzat_wasl>ال</hamzat_wasl><ghunnah>نَّارِ</ghunnah> ذَاتِ <hamzat_wasl>الْ</hamzat_wasl>وَ<tafkhim>قُودِ</tafkhim>", "An-nari dhatil-waqud", "[Containing] the fire full of fuel,", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH, TajweedRuleType.TAFKHIM)),
            make(85, "Al-Buruj", 6, "إِذْ هُمْ عَلَيْهَا قُعُودٌ", "إِذْ هُمْ عَلَيْهَا <tafkhim>قُعُودٌ</tafkhim>", "Idh hum 'alayha qu'ud", "When they were sitting near it", listOf(TajweedRuleType.TAFKHIM)),
            make(85, "Al-Buruj", 7, "وَهُمْ عَلَىٰ مَا يَفْعَلُونَ بِالْمُؤْمِنِينَ شُهُودٌ", "وَهُمْ عَلَىٰ مَا يَفْعَلُونَ بِ<hamzat_wasl>الْ</hamzat_wasl>مُؤْمِنِينَ شُهُودٌ", "Wa hum 'ala ma yaf'aluna bil-mu'minina shuhud", "And they, over what they were doing to the believers, were witnesses.", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(85, "Al-Buruj", 8, "وَمَا نَقَمُوا مِنْهُمْ إِلَّا أَن يُؤْمِنُوا بِاللَّهِ الْعَزِيزِ الْحَمِيدِ", "وَمَا <tafkhim>نَقَمُوا</tafkhim> مِنْهُمْ إِلَّا <madd>أَن</madd> <idgham>يُؤْمِنُوا</idgham> بِ<hamzat_wasl>ال</hamzat_wasl><tafkhim>لَّهِ</tafkhim> <hamzat_wasl>الْ</hamzat_wasl>عَزِيزِ <hamzat_wasl>الْ</hamzat_wasl>حَمِيدِ", "Wa ma naqamu minhum illa ay yu'minu bil-lahil-'azizil-hamid", "And they resented them not except because they believed in Allah, the Exalted in Might, the Praiseworthy,", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.MADD, TajweedRuleType.IDGHAM, TajweedRuleType.HAMZAT_WASL)),
            make(85, "Al-Buruj", 9, "الَّذِي لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ ۚ وَاللَّهُ عَلَىٰ كُلِّ شَيْءٍ شَهِيدٌ", "<hamzat_wasl>الَّذِي</hamzat_wasl> لَهُ مُلْكُ <hamzat_wasl>ال</hamzat_wasl>سَّمَاوَاتِ وَ<hamzat_wasl>الْ</hamzat_wasl>أَرْضِ ۚ وَ<hamzat_wasl>ال</hamzat_wasl><tafkhim>لَّهُ</tafkhim> عَلَىٰ كُلِّ شَيْءٍ شَهِيدٌ", "Alladhi lahu mulkus-samawati wal-ard, wal-lahu 'ala kulli shay'in shahid", "To whom belongs the dominion of the heavens and the earth. And Allah, over all things, is Witness.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(85, "Al-Buruj", 10, "إِنَّ الَّذِينَ فَتَنُوا الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ ثُمَّ لَمْ يَتُوبُوا فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ الْحَرِيقِ", "<ghunnah>إِنَّ</ghunnah> <hamzat_wasl>الَّذِينَ</hamzat_wasl> فَتَنُوا <hamzat_wasl>الْ</hamzat_wasl>مُؤْمِنِينَ وَ<hamzat_wasl>الْ</hamzat_wasl>مُؤْمِنَاتِ <ghunnah>ثُمَّ</ghunnah> لَمْ يَتُوبُوا فَلَهُمْ عَذَابُ <ghunnah>جَهَنَّمَ</ghunnah> وَلَهُمْ عَذَابُ <hamzat_wasl>الْ</hamzat_wasl>حَرِي<qalqalah>قِ</qalqalah>", "Innal-ladhina fatanul-mu'minina wal-mu'minati thumma lam yatubu falahum 'adhabu jahannama wa lahum 'adhabul-hariq", "Indeed, those who have tortured the believing men and believing women and then have not repented will have the punishment of Hell, and they will have the punishment of the Burning Fire.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.QALQALAH)),
            make(85, "Al-Buruj", 11, "إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ ۚ ذَٰلِكَ الْفَوْزُ الْكَبِيرُ", "<ghunnah>إِنَّ</ghunnah> <hamzat_wasl>الَّذِينَ</hamzat_wasl> <madd>آمَنُوا</madd> وَعَمِلُوا <hamzat_wasl>ال</hamzat_wasl><tafkhim>صَّالِحَاتِ</tafkhim> لَهُمْ <ghunnah>جَنَّاتٌ</ghunnah> <ikhfa><qalqalah>تَجْرِي</qalqalah></ikhfa> مِن <ikhfa>تَحْتِهَا</ikhfa> <hamzat_wasl>الْ</hamzat_wasl>أَنْهَارُ ۚ ذَٰلِكَ <hamzat_wasl>الْ</hamzat_wasl>فَوْزُ <hamzat_wasl>الْ</hamzat_wasl>كَبِيرُ", "Innal-ladhina amanu wa 'amilus-salihati lahum jannatun tajri min tahtihal-anhar, dhalikal-fawzul-kabir", "Indeed, those who have believed and done righteous deeds will have gardens beneath which rivers flow. That is the great attainment.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD, TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),
            make(85, "Al-Buruj", 12, "إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ", "<ghunnah>إِنَّ</ghunnah> <tafkhim>بَ</tafkhim><qalqalah>طْ</qalqalah>شَ رَبِّكَ لَشَدِيدٌ", "Inna batsha rabbika lashadid", "Indeed, the vengeance of your Lord is severe.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),
            make(85, "Al-Buruj", 13, "إِنَّهُ هُوَ يُبْدِئُ وَيُعِيدُ", "<ghunnah>إِنَّهُ</ghunnah> هُوَ <qalqalah>يُبْدِئُ</qalqalah> وَيُعِيدُ", "Innahu huwa yubdi'u wa yu'id", "Indeed, it is He who originates [creation] and repeats.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.QALQALAH)),
            make(85, "Al-Buruj", 14, "وَهُوَ الْغَفُورُ الْوَدُودُ", "وَهُوَ <hamzat_wasl>الْ</hamzat_wasl>غَفُورُ <hamzat_wasl>الْ</hamzat_wasl>وَدُودُ", "Wa huwal-ghafrul-wadud", "And He is the Forgiving, the Affectionate,", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(85, "Al-Buruj", 15, "ذُو الْعَرْشِ الْمَجِيدُ", "ذُو <hamzat_wasl>الْ</hamzat_wasl>عَرْشِ <hamzat_wasl>الْ</hamzat_wasl>مَجِيدُ", "Dhul-'arshil-majid", "Honorable Owner of the Throne,", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(85, "Al-Buruj", 16, "فَعَّالٌ لِّمَا يُرِيدُ", "فَعَّالٌ <idgham>لِّمَا</idgham> يُرِيدُ", "Fa''alul lima yurid", "Effecter of what He intends.", listOf(TajweedRuleType.IDGHAM)),
            make(85, "Al-Buruj", 17, "هَلْ أَتَاكَ حَدِيثُ الْجُنُودِ", "هَلْ أَتَاكَ حَدِيثُ <hamzat_wasl>الْ</hamzat_wasl>جُنُودِ", "Hal ataka hadithul-junud", "Has there reached you the story of the soldiers -", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(85, "Al-Buruj", 18, "فِرْعَوْنَ وَثَمُودَ", "فِرْعَوْنَ وَثَمُودَ", "Fir'awna wa Thamud", "[Those of] Pharaoh and Thamud?", emptyList()),
            make(85, "Al-Buruj", 19, "بَلِ الَّذِينَ كَفَرُوا فِي تَكْذِيبٍ", "بَلِ <hamzat_wasl>الَّذِينَ</hamzat_wasl> كَفَرُوا فِي تَكْذِيبٍ", "Balil-ladhina kafaru fi takdhib", "But they who disbelieve are in [persistent] denial,", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(85, "Al-Buruj", 20, "وَاللَّهُ مِن وَرَائِهِم مُّحِيطٌ", "وَ<hamzat_wasl>ال</hamzat_wasl><tafkhim>لَّهُ</tafkhim> مِن <idgham>وَرَائِهِم</idgham> <idgham>مُّحِيطٌ</idgham>", "Wal-lahu miw wara'ihim muhit", "While Allah encompasses them from behind.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM, TajweedRuleType.IDGHAM, TajweedRuleType.MADD)),
            make(85, "Al-Buruj", 21, "بَلْ هُوَ قُرْآنٌ مَّجِيدٌ", "بَلْ هُوَ <tafkhim>قُرْآنٌ</tafkhim> <idgham>مَّجِيدٌ</idgham>", "Bal huwa qur'anum majid", "But this is an honored Qur'an", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.IDGHAM)),
            make(85, "Al-Buruj", 22, "فِي لَوْحٍ مَّحْفُوظٍ", "فِي لَوْحٍ <idgham>مَّحْفُوظٍ</idgham>", "Fi lawhim mahfuz", "[Inscribed] in a Preserved Slate.", listOf(TajweedRuleType.IDGHAM, TajweedRuleType.TAFKHIM)),

            // ==================== SURAH 86: AT-TARIQ (17 Verses) ====================
            make(86, "At-Tariq", 1, "وَالسَّمَاءِ وَالطَّارِقِ", "وَ<hamzat_wasl>ال</hamzat_wasl><madd>سَّمَاءِ</madd> وَ<hamzat_wasl>ال</hamzat_wasl><tafkhim>طَّارِقِ</tafkhim>", "Was-sama'i wat-tariq", "By the sky and the night comer -", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD, TajweedRuleType.TAFKHIM)),
            make(86, "At-Tariq", 2, "وَمَا أَدْرَاكَ مَا الطَّارِقُ", "وَمَا <madd>أَ</madd><qalqalah>دْرَاكَ</qalqalah> مَا <hamzat_wasl>ال</hamzat_wasl><tafkhim>طَّارِقُ</tafkhim>", "Wa ma adraka mat-tariq", "And what can make you know what is the night comer?", listOf(TajweedRuleType.MADD, TajweedRuleType.QALQALAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(86, "At-Tariq", 3, "النَّجْمُ الثَّاقِبُ", "<hamzat_wasl>ال</hamzat_wasl><ghunnah>نَّجْمُ</ghunnah> <hamzat_wasl>ال</hamzat_wasl>ثَّاقِ<qalqalah>بُ</qalqalah>", "An-najmuth-thaqib", "It is the piercing star -", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH, TajweedRuleType.QALQALAH)),
            make(86, "At-Tariq", 4, "إِن كُلُّ نَفْسٍ لَّمَّا عَلَيْهَا حَافِظٌ", "إِن <ikhfa>كُلُّ</ikhfa> نَفْسٍ <idgham>لَّمَّا</idgham> عَلَيْهَا حَافِظٌ", "In kullu nafsil lamma 'alayha hafiz", "There is no soul but that it has over it a protector.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.IDGHAM)),
            make(86, "At-Tariq", 5, "فَلْيَنظُرِ الْإِنسَانُ مِمَّ خُلِقَ", "فَلْيَن<ikhfa>ظُرِ</ikhfa> <hamzat_wasl>الْ</hamzat_wasl>إِ<ikhfa>نسَانُ</ikhfa> <ghunnah>مِمَّ</ghunnah> خُلِ<qalqalah>قَ</qalqalah>", "Falyanzuril-insanu mimma khuliq", "So let man observe from what he was created.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.QALQALAH)),
            make(86, "At-Tariq", 6, "خُلِقَ مِن مَّاءٍ دَافِقٍ", "خُلِ<tafkhim>قَ</tafkhim> مِن <idgham>مَّ</idgham><madd>اءٍ</madd> <ikhfa>دَافِقٍ</ikhfa>", "Khuliqa mim ma'in dafiq", "He was created from a fluid, ejected,", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.IDGHAM, TajweedRuleType.MADD, TajweedRuleType.GHUNNAH)),
            make(86, "At-Tariq", 7, "يَخْرُجُ مِن بَيْنِ الصُّلْبِ وَالتَّرَائِبِ", "يَخْرُجُ مِن <iqlab>بَيْنِ</iqlab> <hamzat_wasl>ال</hamzat_wasl><tafkhim>صُّلْبِ</tafkhim> وَ<hamzat_wasl>ال</hamzat_wasl>تَّ<madd>رَائِبِ</madd>", "Yakhruju mim baynis-sulbi wat-tara'ib", "Emerging from between the backbone and the ribs.", listOf(TajweedRuleType.IQLAB, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM, TajweedRuleType.MADD)),
            make(86, "At-Tariq", 8, "إِنَّهُ عَلَىٰ رَجْعِهِ لَقَادِرٌ", "<ghunnah>إِنَّهُ</ghunnah> عَلَىٰ <qalqalah>رَجْعِهِ</qalqalah> لَ<tafkhim>قَادِرٌ</tafkhim>", "Innahu 'ala raj'ihi laqadir", "Indeed, Allah, to return him [to life], is Able.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.QALQALAH, TajweedRuleType.TAFKHIM)),
            make(86, "At-Tariq", 9, "يَوْمَ تُبْلَى السَّرَائِرُ", "يَوْمَ <qalqalah>تُبْلَى</qalqalah> <hamzat_wasl>ال</hamzat_wasl>سَّ<madd>رَائِرُ</madd>", "Yawma tublas-sara'ir", "The Day when secrets will be disclosed,", listOf(TajweedRuleType.QALQALAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD)),
            make(86, "At-Tariq", 10, "فَمَا لَهُ مِن قُوَّةٍ وَلَا نَاصِرٍ", "فَمَا لَهُ مِن <ikhfa><tafkhim>قُوَّةٍ</tafkhim></ikhfa> <idgham>وَلَا</idgham> نَاصِرٍ", "Fama lahu min quwwatiw wa la nasir", "Then the man will have no power or any helper.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.TAFKHIM, TajweedRuleType.IDGHAM)),
            make(86, "At-Tariq", 11, "وَالسَّمَاءِ ذَاتِ الرَّجْعِ", "وَ<hamzat_wasl>ال</hamzat_wasl><madd>سَّمَاءِ</madd> ذَاتِ <hamzat_wasl>ال</hamzat_wasl>رَّ<qalqalah>جْعِ</qalqalah>", "Was-sama'i dhatir-raj'", "By the sky which returns [rain]", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD, TajweedRuleType.QALQALAH)),
            make(86, "At-Tariq", 12, "وَالْأَرْضِ ذَاتِ الصَّدْعِ", "وَ<hamzat_wasl>الْ</hamzat_wasl>أَرْضِ ذَاتِ <hamzat_wasl>ال</hamzat_wasl><tafkhim>صَّدْعِ</tafkhim>", "Wal-ardi dhatis-sad'", "And [by] the earth which splits open [with plants],", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(86, "At-Tariq", 13, "إِنَّهُ لَقَوْلٌ فَصْلٌ", "<ghunnah>إِنَّهُ</ghunnah> لَ<tafkhim>قَوْلٌ</tafkhim> <ikhfa><tafkhim>فَصْلٌ</tafkhim></ikhfa>", "Innahu laqawlun fasl", "Indeed, the Qur'an is a decisive statement,", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.TAFKHIM)),
            make(86, "At-Tariq", 14, "وَمَا هُوَ بِالْهَزْلِ", "وَمَا هُوَ بِ<hamzat_wasl>الْ</hamzat_wasl>هَزْلِ", "Wa ma huwa bil-hazl", "And it is not amusement.", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(86, "At-Tariq", 15, "إِنَّهُمْ يَكِيدُونَ كَيْدًا", "<ghunnah>إِنَّهُمْ</ghunnah> يَكِيدُونَ كَيْدًا", "Innahum yakiduna kayda", "Indeed, they are planning a plan,", listOf(TajweedRuleType.GHUNNAH)),
            make(86, "At-Tariq", 16, "وَأَكِيدُ كَيْدًا", "وَأَكِيدُ كَيْدًا", "Wa akidu kayda", "But I am planning a plan.", emptyList()),
            make(86, "At-Tariq", 17, "فَمَهِّلِ الْكَافِرِينَ أَمْهِلْهُمْ رُوَيْدًا", "فَمَهِّلِ <hamzat_wasl>الْ</hamzat_wasl>كَافِرِينَ أَمْهِلْهُمْ رُوَيْدًا", "Famahhilil-kafirina amhilhum ruwayda", "So allow time for the disbelievers. Leave them awhile.", listOf(TajweedRuleType.HAMZAT_WASL)),

            // ==================== SURAH 87: AL-A'LA (19 Verses) ====================
            make(87, "Al-A'la", 1, "سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى", "سَبِّحِ <hamzat_wasl>ا</hamzat_wasl>سْمَ رَبِّكَ <hamzat_wasl>الْ</hamzat_wasl>أَعْلَى", "Sabbihisma rabbikal-a'la", "Exalt the name of your Lord, the Most High,", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(87, "Al-A'la", 2, "الَّذِي خَلَقَ فَسَوَّىٰ", "<hamzat_wasl>الَّذِي</hamzat_wasl> خَلَ<tafkhim>قَ</tafkhim> فَسَوَّىٰ", "Alladhi khalaqa fasawwa", "Who created and proportioned", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(87, "Al-A'la", 3, "وَالَّذِي قَدَّرَ فَهَدَىٰ", "وَ<hamzat_wasl>الَّذِي</hamzat_wasl> <tafkhim>قَدَّرَ</tafkhim> فَهَدَىٰ", "Walladhi qaddara fahada", "And who destined and [then] guided", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(87, "Al-A'la", 4, "وَالَّذِي أَخْرَجَ الْمَرْعَىٰ", "وَ<hamzat_wasl>الَّذِي</hamzat_wasl> أَخْرَجَ <hamzat_wasl>الْ</hamzat_wasl>مَرْعَىٰ", "Walladhi akhrajal-mar'a", "And who brings out the pasture", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(87, "Al-A'la", 5, "فَجَعَلَهُ غُثَاءً أَحْوَىٰ", "فَجَعَلَهُ <madd>غُثَاءً</madd> أَحْوَىٰ", "Faja'alahu ghutha'an ahwa", "And [then] makes it black stubble.", listOf(TajweedRuleType.MADD)),
            make(87, "Al-A'la", 6, "سَنُقْرِئُكَ فَلَا تَنسَىٰ", "سَنُ<tafkhim>قْ</tafkhim><qalqalah>رِئُكَ</qalqalah> فَلَا تَن<ikhfa>سَىٰ</ikhfa>", "Sanuqri'uka fala tansa", "We will make you recite, [O Muhammad], and you will not forget,", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH, TajweedRuleType.GHUNNAH)),
            make(87, "Al-A'la", 7, "إِلَّا مَا شَاءَ اللَّهُ ۚ إِنَّهُ يَعْلَمُ الْجَهْرَ وَمَا يَخْفَىٰ", "إِلَّا مَا <madd>شَاءَ</madd> <hamzat_wasl>ال</hamzat_wasl><tafkhim>لَّهُ</tafkhim> ۚ <ghunnah>إِنَّهُ</ghunnah> يَعْلَمُ <hamzat_wasl>الْ</hamzat_wasl>جَهْرَ وَمَا يَخْفَىٰ", "Illa ma sha'al-lah, innahu ya'lamul-jahra wa ma yakhfa", "Except what Allah should will. Indeed, He knows what is declared and what is hidden.", listOf(TajweedRuleType.MADD, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM, TajweedRuleType.GHUNNAH)),
            make(87, "Al-A'la", 8, "وَنُيَسِّرُكَ لِلْيُسْرَىٰ", "وَنُيَسِّرُكَ لِلْيُسْرَىٰ", "Wa nuyassiruka lil-yusra", "And We will ease you toward ease.", emptyList()),
            make(87, "Al-A'la", 9, "فَذَكِّرْ إِن نَّفَعَتِ الذِّكْرَىٰ", "فَذَكِّرْ إِن <idgham>نَّفَعَتِ</idgham> <hamzat_wasl>ال</hamzat_wasl>ذِّكْرَىٰ", "Fadhakkir in nafa'atidh-dhikra", "So remind, if the reminder should benefit;", listOf(TajweedRuleType.IDGHAM, TajweedRuleType.HAMZAT_WASL)),
            make(87, "Al-A'la", 10, "سَيَذَّكَّرُ مَن يَخْشَىٰ", "سَيَذَّكَّرُ مَن <idgham>يَخْشَىٰ</idgham>", "Sayadh-dhakkaru may yakhsha", "He who fears [Allah] will be reminded.", listOf(TajweedRuleType.IDGHAM)),
            make(87, "Al-A'la", 11, "وَيَتَجَنَّبُهَا الْأَشْقَى", "وَيَتَ<ghunnah>جَنَّبُهَا</ghunnah> <hamzat_wasl>الْ</hamzat_wasl>أَ<tafkhim>شْقَى</tafkhim>", "Wa yatajannabuhal-ashqa", "But the wretched one will avoid it -", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(87, "Al-A'la", 12, "الَّذِي يَصْلَى النَّارَ الْكُبْرَىٰ", "<hamzat_wasl>الَّذِي</hamzat_wasl> <tafkhim>يَصْلَى</tafkhim> <hamzat_wasl>ال</hamzat_wasl><ghunnah>نَّارَ</ghunnah> <hamzat_wasl>الْ</hamzat_wasl>كُ<qalqalah>بْ</qalqalah>رَىٰ", "Alladhi yaslan-naral-kubra", "[He] who will [enter and] burn in the greatest Fire,", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM, TajweedRuleType.GHUNNAH, TajweedRuleType.QALQALAH)),
            make(87, "Al-A'la", 13, "ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ", "<ghunnah>ثُمَّ</ghunnah> لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ", "Thumma la yamutu fiha wa la yahya", "Neither dying therein nor living.", listOf(TajweedRuleType.GHUNNAH)),
            make(87, "Al-A'la", 14, "قَدْ أَفْلَحَ مَن تَزَكَّىٰ", "<tafkhim><qalqalah>قَدْ</qalqalah></tafkhim> أَفْلَحَ مَن <ikhfa>تَزَكَّىٰ</ikhfa>", "Qad aflaha man tazakka", "He has certainly succeeded who purifies himself", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH, TajweedRuleType.GHUNNAH)),
            make(87, "Al-A'la", 15, "وَذَكَرَ اسْمَ رَبِّهِ فَصَلَّىٰ", "وَذَكَرَ <hamzat_wasl>ا</hamzat_wasl>سْمَ رَبِّهِ فَ<tafkhim>صَلَّىٰ</tafkhim>", "Wa dhakarasma rabbihi fasalla", "And mentions the name of his Lord and prays.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(87, "Al-A'la", 16, "بَلْ تُؤْثِرُونَ الْحَيَاةَ الدُّنْيَا", "بَلْ تُؤْثِرُونَ <hamzat_wasl>الْ</hamzat_wasl>حَيَاةَ <hamzat_wasl>ال</hamzat_wasl>دُّنْيَا", "Bal tu'thirunal-hayatad-dunya", "But you prefer the worldly life,", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(87, "Al-A'la", 17, "وَالْآخِرَةُ خَيْرٌ وَأَبْقَىٰ", "وَ<hamzat_wasl>الْ</hamzat_wasl><madd>آخِرَةُ</madd> خَيْرٌ <idgham>وَ</idgham>أَ<qalqalah>بْ</qalqalah><tafkhim>قَىٰ</tafkhim>", "Wal-akhiratu khayruw wa abqa", "While the Hereafter is better and more enduring.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD, TajweedRuleType.IDGHAM, TajweedRuleType.QALQALAH, TajweedRuleType.TAFKHIM)),
            make(87, "Al-A'la", 18, "إِنَّ هَٰذَا لَفِي الصُّحُفِ الْأُولَىٰ", "<ghunnah>إِنَّ</ghunnah> هَٰذَا لَفِي <hamzat_wasl>ال</hamzat_wasl><tafkhim>صُّحُفِ</tafkhim> <hamzat_wasl>الْ</hamzat_wasl>أُولَىٰ", "Inna hadha lafis-suhufil-ula", "Indeed, this is in the former scriptures,", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(87, "Al-A'la", 19, "صُحُفِ إِبْرَاهِيمَ وَمُوسَىٰ", "<tafkhim>صُحُفِ</tafkhim> <madd>إِ</madd><qalqalah>بْ</qalqalah>رَاهِيمَ وَمُوسَىٰ", "Suhufi Ibrahima wa Musa", "The scriptures of Abraham and Moses.", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.MADD, TajweedRuleType.QALQALAH)),

            // ==================== SURAH 88: AL-GHASHIYAH (26 Verses) ====================
            make(88, "Al-Ghashiyah", 1, "هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ", "هَلْ أَتَاكَ حَدِيثُ <hamzat_wasl>الْ</hamzat_wasl>غَاشِيَةِ", "Hal ataka hadithul-ghashiyah", "Has there reached you the report of the Overwhelming [event]?", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(88, "Al-Ghashiyah", 2, "وُجُوهٌ يَوْمَئِذٍ خَاشِعَةٌ", "وُجُوهٌ <idgham>يَوْمَئِذٍ</idgham> خَاشِعَةٌ", "Wujuhuy yawma'idhin khashi'ah", "[Some] faces, that Day, will be humbled,", listOf(TajweedRuleType.IDGHAM)),
            make(88, "Al-Ghashiyah", 3, "عَامِلَةٌ نَّاصِبَةٌ", "عَامِلَةٌ <idgham>نَّاصِبَةٌ</idgham>", "'Amilatun nasibah", "Working [hard] and exhausted.", listOf(TajweedRuleType.IDGHAM)),
            make(88, "Al-Ghashiyah", 4, "تَصْلَىٰ نَارًا حَامِيَةً", "<tafkhim>تَصْلَىٰ</tafkhim> نَارًا حَامِيَةً", "Tasla naran hamiyah", "They will [enter to] burn in an intensely hot Fire.", listOf(TajweedRuleType.TAFKHIM)),
            make(88, "Al-Ghashiyah", 5, "تُسْقَىٰ مِنْ عَيْنٍ آنِيَةٍ", "تُسْ<tafkhim>قَىٰ</tafkhim> مِنْ عَيْنٍ <madd>آنِيَةٍ</madd>", "Tusqa min 'aynin aniyah", "They will be given drink from a boiling spring.", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.MADD)),
            make(88, "Al-Ghashiyah", 6, "لَّيْسَ لَهُمْ طَعَامٌ إِلَّا مِن ضَرِيعٍ", "لَّيْسَ لَهُمْ <tafkhim>طَعَامٌ</tafkhim> إِلَّا مِن <ikhfa><tafkhim>ضَرِيعٍ</tafkhim></ikhfa>", "Laysa lahum ta'amun illa min dari'", "For them there will be no food except from a poisonous, thorny plant", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.GHUNNAH)),
            make(88, "Al-Ghashiyah", 7, "لَّا يُسْمِنُ وَلَا يُغْنِي مِن جُوعٍ", "لَّا يُسْمِنُ <idgham>وَلَا</idgham> يُغْنِي مِن <ikhfa>جُوعٍ</ikhfa>", "La yusminu wa la yughni min ju'", "Which neither nourishes nor avails against hunger.", listOf(TajweedRuleType.IDGHAM, TajweedRuleType.GHUNNAH)),
            make(88, "Al-Ghashiyah", 8, "وُجُوهٌ يَوْمَئِذٍ نَّاعِمَةٌ", "وُجُوهٌ <idgham>يَوْمَئِذٍ</idgham> <idgham>نَّاعِمَةٌ</idgham>", "Wujuhuy yawma'idhin na'imah", "[Other] faces, that Day, will show pleasure.", listOf(TajweedRuleType.IDGHAM)),
            make(88, "Al-Ghashiyah", 9, "لِّسَعْيِهَا رَاضِيَةٌ", "لِّسَعْيِهَا <tafkhim>رَاضِيَةٌ</tafkhim>", "Lisa'yiha radiyah", "With their effort [they are] satisfied", listOf(TajweedRuleType.TAFKHIM)),
            make(88, "Al-Ghashiyah", 10, "فِي جَنَّةٍ عَالِيَةٍ", "فِي <ghunnah>جَنَّةٍ</ghunnah> عَالِيَةٍ", "Fi jannatin 'aliyah", "In an elevated garden,", listOf(TajweedRuleType.GHUNNAH)),
            make(88, "Al-Ghashiyah", 11, "لَّا تَسْمَعُ فِيهَا لَاغِيَةً", "لَّا تَسْمَعُ فِيهَا لَاغِيَةً", "La tasma'u fiha laghiyah", "Where they will hear no unsuitable speech.", emptyList()),
            make(88, "Al-Ghashiyah", 12, "فِيهَا عَيْنٌ جَارِيَةٌ", "فِيهَا عَيْنٌ <ikhfa>جَارِيَةٌ</ikhfa>", "Fiha 'aynun jariyah", "Within it is a flowing spring.", listOf(TajweedRuleType.GHUNNAH)),
            make(88, "Al-Ghashiyah", 13, "فِيهَا سُرُرٌ مَّرْفُوعَةٌ", "فِيهَا سُرُرٌ <idgham>مَّرْفُوعَةٌ</idgham>", "Fiha sururum marfu'ah", "Within it are couches raised high", listOf(TajweedRuleType.IDGHAM)),
            make(88, "Al-Ghashiyah", 14, "وَأَكْوَابٌ مَّوْضُوعَةٌ", "وَأَكْوَابٌ <idgham>مَّوْ</idgham><tafkhim>ضُوعَةٌ</tafkhim>", "Wa akwabum mawdu'ah", "And cups put in place", listOf(TajweedRuleType.IDGHAM, TajweedRuleType.TAFKHIM)),
            make(88, "Al-Ghashiyah", 15, "وَنَمَارِقُ مَصْفُوفَةٌ", "وَنَمَارِ<tafkhim>قُ</tafkhim> <tafkhim>مَصْفُوفَةٌ</tafkhim>", "Wa namariqu masfufah", "And cushions lined up", listOf(TajweedRuleType.TAFKHIM)),
            make(88, "Al-Ghashiyah", 16, "وَزَرَابِيُّ مَبْثُوثَةٌ", "وَزَرَابِيُّ مَ<qalqalah>بْ</qalqalah>ثُوثَةٌ", "Wa zarabiyyu mabthuthah", "And carpets spread around.", listOf(TajweedRuleType.QALQALAH)),
            make(88, "Al-Ghashiyah", 17, "أَفَلَا يَنظُرُونَ إِلَى الْإِبِلِ كَيْفَ خُلِقَتْ", "أَفَلَا يَن<ikhfa>ظُرُونَ</ikhfa> إِلَى <hamzat_wasl>الْ</hamzat_wasl>إِبِلِ كَيْفَ خُلِ<tafkhim>قَتْ</tafkhim>", "Afala yanzuruna ilal-ibili kayfa khuliqat", "Then do they not look at the camels - how they are created?", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(88, "Al-Ghashiyah", 18, "وَإِلَى السَّمَاءِ كَيْفَ رُفِعَتْ", "وَإِلَى <hamzat_wasl>ال</hamzat_wasl><madd>سَّمَاءِ</madd> كَيْفَ رُفِعَتْ", "Wa ilas-sama'i kayfa rufi'at", "And at the sky - how it is raised?", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD)),
            make(88, "Al-Ghashiyah", 19, "وَإِلَى الْجِبَالِ كَيْفَ نُصِبَتْ", "وَإِلَى <hamzat_wasl>الْ</hamzat_wasl>جِبَالِ كَيْفَ <tafkhim>نُصِبَتْ</tafkhim>", "Wa ilal-jibali kayfa nusibat", "And at the mountains - how they are erected?", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(88, "Al-Ghashiyah", 20, "وَإِلَى الْأَرْضِ كَيْفَ سُطِحَتْ", "وَإِلَى <hamzat_wasl>الْ</hamzat_wasl>أَرْضِ كَيْفَ <tafkhim>سُطِحَتْ</tafkhim>", "Wa ilal-ardi kayfa sutihat", "And at the earth - how it is spread out?", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(88, "Al-Ghashiyah", 21, "فَذَكِّرْ إِنَّمَا أَنتَ مُذَكِّرٌ", "فَذَكِّرْ <ghunnah>إِنَّمَا</ghunnah> <madd>أَ</madd><ikhfa>نتَ</ikhfa> مُذَكِّرٌ", "Fadhakkir innama anta mudhakkir", "So remind, [O Muhammad]; you are only a reminder.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.MADD)),
            make(88, "Al-Ghashiyah", 22, "لَّسْتَ عَلَيْهِم بِمُصَيْطِرٍ", "لَّسْتَ عَلَيْهِم <ikhfa>بِمُ</ikhfa><tafkhim>صَيْطِرٍ</tafkhim>", "Lasta 'alayhim bimusaytir", "You are not over them a controller.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.TAFKHIM)),
            make(88, "Al-Ghashiyah", 23, "إِلَّا مَن تَوَلَّىٰ وَكَفَرَ", "إِلَّا مَن <ikhfa>تَوَلَّىٰ</ikhfa> وَكَفَرَ", "Illa man tawalla wa kafar", "However, he who turns away and disbelieves -", listOf(TajweedRuleType.GHUNNAH)),
            make(88, "Al-Ghashiyah", 24, "فَيُعَذِّبُهُ اللَّهُ الْعَذَابَ الْأَكْبَرَ", "فَيُعَذِّبُهُ <hamzat_wasl>ال</hamzat_wasl><tafkhim>لَّهُ</tafkhim> <hamzat_wasl>الْ</hamzat_wasl>عَذَابَ <hamzat_wasl>الْ</hamzat_wasl>أَ<qalqalah>كْبَرَ</qalqalah>", "Fayu'adhdhibuhul-lahul-'adhabal-akbar", "Then Allah will punish him with the greatest punishment.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),
            make(88, "Al-Ghashiyah", 25, "إِنَّ إِلَيْنَا إِيَابَهُمْ", "<ghunnah>إِنَّ</ghunnah> <madd>إِلَيْنَا</madd> <madd>إِيَابَهُمْ</madd>", "Inna ilayna iyabahum", "Indeed, to Us is their return", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.MADD)),
            make(88, "Al-Ghashiyah", 26, "ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُم", "<ghunnah>ثُمَّ</ghunnah> <ghunnah>إِنَّ</ghunnah> عَلَيْنَا حِسَابَهُم", "Thumma inna 'alayna hisabahum", "Then indeed, upon Us is their account.", listOf(TajweedRuleType.GHUNNAH))
        )
    }
